{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(min(duration)/1e6,1) mn, round(approx_quantile(duration,0.5)/1e6,1) p50, round(max(duration)/1e6,1) mx FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2,3 ORDER BY 1,2",
          "claim": "In the incident, travel-service 'SELECT ts.trip' DB client spans all error after about 26.7s; normal runs take about 0.6ms."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, substr(message,1,160) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND level IN ('ERROR','WARN','SEVERE') GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Travel-service logs HikariPool connection timeouts after 30000ms, 'Communications link failure' and SQL Error 08S01 from its database driver."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),2) v, round(max(value),2) mx FROM abnormal_metrics_sum WHERE service_name='ts-travel-service' AND metric LIKE 'db.client.connections%' GROUP BY 1 ORDER BY 1",
          "claim": "Travel-service connection pool (max 10) shows pending requests and connection timeouts during the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name cname, s.service_name callee, s.span_name sname, count(*) n, approx_quantile(c.duration,0.5)/1e6 caller_ms, approx_quantile(s.duration,0.5)/1e6 callee_ms, max(s.attr_http_response_status_code) st FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY 1,2,3,4 ORDER BY caller_ms DESC",
          "claim": "Route-plan calls to travel-service /trips/left take about 28s and return HTTP 500 in the incident."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name cname, s.service_name callee, s.span_name sname, count(*) n, approx_quantile(c.duration,0.5)/1e6 caller_ms, approx_quantile(s.duration,0.5)/1e6 callee_ms, max(s.attr_http_response_status_code) st FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-route-plan-service' GROUP BY 1,2,3,4 ORDER BY caller_ms DESC",
          "claim": "Travel-plan calls to route-plan routePlan endpoints take 19-30s and return HTTP 500 in the incident."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code st, count(*) n, approx_quantile(duration,0.5)/1e6 p50 FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name='ts-ui-dashboard' AND span_name LIKE '%travelPlan%' GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "Ui-dashboard travelPlan requests take about 15-20s, because the chain beneath them is failing and slow."
        }
      ]
    }
  ]
}

